      (3, 13897, 3, 'FCCF3AFB', '3152038583', null, '2026-08-31', '2026-09-04 08:51:50', '2026-08-31', 2706, 2706, null, 1007, 1375, 7.7, 'V', 'SRV', null, null, 'SRV', '2026-09-04 00:00:00', 'V', 2026, 8, 7, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 1, 2026, null, 8, 0, 0, 0, null, null, null, null, 'C', true, 10, 2, null, null),
